package tri_lion.health.service.health;
import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tri_lion.health.domain.health.*;import tri_lion.health.exception.ApiException;import tri_lion.health.repository.health.HealthRepositories;import tri_lion.health.security.AuthenticatedUser;
@Service public class AnalysisService {private final HealthRepositories.Analyses analyses;private final HealthRepositories.Documents docs;private final HealthRepositories.Jobs jobs;private final JdbcTemplate jdbc;private final ObjectMapper json;private final AuthenticatedUser auth;public AnalysisService(HealthRepositories.Analyses a,HealthRepositories.Documents d,HealthRepositories.Jobs j,JdbcTemplate db,ObjectMapper o,AuthenticatedUser au){analyses=a;docs=d;jobs=j;jdbc=db;json=o;auth=au;}@Transactional public Analysis create(List<Long> ids,String key){Long uid=auth.sensitive().getId();if(ids==null||ids.isEmpty())throw new IllegalArgumentException("분석할 문서가 필요합니다.");for(Long id:ids)docs.findByIdAndUserIdAndDeletedAtIsNull(id,uid).orElseThrow(()->ApiException.notFound("건강 문서를 찾을 수 없습니다."));if(key!=null){var existing=jobs.findByUserIdAndTypeAndIdempotencyKey(uid,AiJob.Type.HEALTH_ANALYSIS,key);if(existing.isPresent())return analyses.findById(existing.get().getResultId()).orElseThrow();}Analysis a=analyses.save(new Analysis(uid));for(Long id:ids)jdbc.update("insert into analysis_documents(analysis_id,document_id) values (?,?)",a.getId(),id);try{jobs.save(new AiJob(uid,AiJob.Type.HEALTH_ANALYSIS,json.writeValueAsString(Map.of("documentIds",ids)),a.getId(),key));}catch(Exception e){throw ApiException.conflict("같은 Idempotency-Key의 요청이 이미 처리되었습니다.");}return a;}public Analysis one(Long id){return analyses.findByIdAndUserId(id,auth.sensitive().getId()).orElseThrow(()->ApiException.notFound("건강 분석을 찾을 수 없습니다."));}public Analysis latest(){return analyses.findFirstByUserIdAndStatusOrderByCompletedAtDesc(auth.sensitive().getId(),Analysis.Status.COMPLETED).orElseThrow(()->ApiException.notFound("완료된 AI 건강 분석이 없습니다."));}public Page<Analysis> list(String status,int page,int size){Long id=auth.sensitive().getId();Pageable p=PageRequest.of(page,Math.min(size,100));return status==null?analyses.findByUserIdOrderByCreatedAtDesc(id,p):analyses.findByUserIdAndStatusOrderByCreatedAtDesc(id,Analysis.Status.valueOf(status),p);}}
